formula.expression:
let(
  /* Pega a data de competência (que será dia 1) */
  dataBase,{{notion:block_property:EI%5BS:a9160e4a-f73d-4c87-b39a-c76d47c25e4a:41905f3c-1b3b-4a04-ba8c-8fbfb89cbff2}},

  /* Pega o dia que você definiu no número (ex: 10) */
  diaAlvo,{{notion:block_property:F%5DpQ:a9160e4a-f73d-4c87-b39a-c76d47c25e4a:41905f3c-1b3b-4a04-ba8c-8fbfb89cbff2}},

  /* Se o dia alvo estiver vazio, não mostra nada. Se tiver preenchido, calcula a data */
  if(empty(diaAlvo), parseDate(""), dateAdd(dataBase, diaAlvo - date(dataBase), "days"))
)
